    </div>
    <div class="chart-box short">
      <div class="chart-title">Maximum Drawdown by Decade (%)</div>
      <div class="chart-wrap"><canvas id="decadeDdChart"></canvas></div>
    </div>
    <div class="chart-box short">
      <div class="chart-title">Dividends Paid Per Share by Decade ($)</div>
      <div class="chart-wrap"><canvas id="decadeDivChart"></canvas></div>
