    <tbody>'''

for ep in a['drawdown_episodes']:
    html += f'<tr><td>{ep["peak_date"]}</td><td class="num">${ep["peak_price"]:,.2f}</td><td>{ep["trough_date"]}</td><td class="num">${ep["trough_price"]:,.2f}</td><td class="num neg">{ep["drawdown"]:.1f}%</td><td class="num">{ep["duration_days"]}</td></tr>'

